import {uid,escapeHTML as e,plain} from './store.js';
import {editorMarkup,mountEditor} from './editor.js';
import {documentTargets} from './document-links.js';
export const defaultMonths=()=>['Aurora','Bruma','Florália','Solalto','Âmbar','Geada'].map(name=>({name,days:30}));
export function initNarrative(w){if(!w.narrative){w.narrative={relations:[],events:[],scenes:[],calendar:{months:defaultMonths(),weekdays:['Sol','Lua','Estrela','Terra','Vento'],era:'Era atual'}};for(const t of ['connections','timeline','scenes'])if(!w.enabled.includes(t))w.enabled.push(t);}const n=w.narrative;if(!Array.isArray(n.relations)||!Array.isArray(n.events)||!Array.isArray(n.scenes)||!Array.isArray(n.calendar?.months)||!n.calendar.months.length||n.calendar.months.some(m=>!Number.isInteger(m.days)||m.days<1||m.days>365)||!Array.isArray(n.calendar.weekdays)||!n.calendar.weekdays.length)throw Error('Dados narrativos inválidos.');return n;}
export function loreTargets(w){return [...documentTargets(w).map(d=>({...d,name:d.title,kind:'Documento',description:plain([...w.notes,...w.folderNotes].find(n=>n.id===d.id)?.body||'')})),...['characters','bestiary','plot'].flatMap(k=>w[k].map(x=>({id:x.id,name:x.name||x.title,kind:k==='characters'?'Personagem':k==='bestiary'?'Criatura':'Trama',description:x.description||''}))),...w.maps.flatMap(m=>m.pins.map(p=>({id:p.id,name:p.name,kind:'Lugar',description:p.description||''})))];}
export function fictionalOrdinal(ev,calendar){return Number(ev.year)*calendar.months.reduce((s,m)=>s+m.days,0)+calendar.months.slice(0,Number(ev.month)).reduce((s,m)=>s+m.days,0)+Number(ev.day)-1;}
export function mountNarrative(main,w,view,{modal,field,save,heading,btn,openDocument,notify,confirmDelete}){
const n=initNarrative(w),targets=loreTargets(w);let dispose=()=>{},selected='',filter='',editing=true;const name=id=>targets.find(t=>t.id===id)?.name||'Referência removida';const options=(id='',empty=true)=>(empty?'<option value="">Sem referência</option>':'')+targets.map(t=>`<option value="${e(t.id)}" ${id===t.id?'selected':''}>${e(t.kind)} · ${e(t.name)}</option>`).join('');
const select=(label,key,value='',empty=true)=>`<label class="field"><span>${label}</span><select name="${key}">${options(value,empty)}</select></label>`;
const dateText=ev=>`${ev.day} de ${n.calendar.months[ev.month]?.name||'?'} · ${ev.year} ${n.calendar.era}`;
function editRelation(id){const r=n.relations.find(x=>x.id===id);if(targets.length<2){notify('Crie pelo menos duas fichas, documentos ou regiões para conectá-los.');return;}modal(r?'Editar conexão':'Uma nova conexão',select('Origem','from',r?.from||targets[0].id,false)+field('Relação','label',r?.label||'Aliado de','text',true)+select('Destino','to',r?.to||targets[1].id,false)+field('Anotações','description',r?.description||'','textarea')+(r?'<button type="button" id="removeRelation" class="text-link">Excluir conexão</button>':''),fd=>{if(fd.get('from')===fd.get('to'))throw Error('Escolha dois itens diferentes.');const data={id:r?.id||uid(),from:fd.get('from'),to:fd.get('to'),label:fd.get('label'),description:fd.get('description')};if(r)Object.assign(r,data);else n.relations.push(data);save();render();});if(r)document.querySelector('#removeRelation').onclick=()=>{document.querySelector('#modal').close();confirmDelete('Excluir conexão?','Os itens conectados serão preservados.',()=>{n.relations=n.relations.filter(x=>x.id!==id);});};}
function editEvent(id){const ev=n.events.find(x=>x.id===id);modal(ev?'Editar evento':'Acontecimento do mundo',field('Título','title',ev?.title||'','text',true)+`<div class="field-grid">${field('Ano (aceita negativos)','year',ev?.year??1,'number',true)}<label class="field"><span>Mês</span><select name="month">${n.calendar.months.map((m,i)=>`<option value="${i}" ${ev?.month===i?'selected':''}>${e(m.name)}</option>`).join('')}</select></label>${field('Dia','day',ev?.day||1,'number',true)}</div>`+select('Referência relacionada','target',ev?.target)+field('Descrição','description',ev?.description||'','textarea')+(ev?'<button type="button" id="removeEvent" class="text-link">Excluir evento</button>':''),fd=>{const year=Number(fd.get('year')),month=Number(fd.get('month')),day=Number(fd.get('day'));if(!Number.isSafeInteger(year)||!Number.isInteger(day)||day<1||day>n.calendar.months[month].days)throw Error('Informe uma data válida para este calendário.');const data={id:ev?.id||uid(),title:fd.get('title'),year,month,day,target:fd.get('target'),description:fd.get('description')};if(ev)Object.assign(ev,data);else n.events.push(data);save();render();});if(ev)document.querySelector('#removeEvent').onclick=()=>{document.querySelector('#modal').close();confirmDelete('Excluir evento?','Este evento será removido da cronologia.',()=>n.events=n.events.filter(x=>x.id!==id));};}
function calendarSettings(){modal('O tempo do seu mundo',field('Era','era',n.calendar.era,'text',true)+field('Meses: um por linha, nome | dias','months',n.calendar.months.map(m=>`${m.name} | ${m.days}`).join('\n'),'textarea',true)+field('Dias da semana, separados por vírgula','weekdays',n.calendar.weekdays.join(', '),'text',true)+'<p class="help">Exemplo: Aurora | 30. As datas dos eventos precisam continuar válidas após as alterações.</p>',fd=>{const months=String(fd.get('months')).split('\n').filter(x=>x.trim()).map(line=>{const parts=line.split('|');return {name:parts[0].trim(),days:Number(parts[1])};}),weekdays=String(fd.get('weekdays')).split(',').map(x=>x.trim()).filter(Boolean);if(!months.length||months.length>30||months.some(m=>!m.name||!Number.isInteger(m.days)||m.days<1||m.days>365)||!weekdays.length||weekdays.length>30)throw Error('Use de 1 a 30 meses e dias da semana; cada mês deve ter de 1 a 365 dias.');if(n.events.some(ev=>!months[ev.month]||ev.day>months[ev.month].days))throw Error('Há eventos em datas que seriam removidas. Ajuste esses eventos primeiro.');n.calendar={era:fd.get('era'),months,weekdays};save();render();});}
function render(){dispose();dispose=()=>{};if(view==='connections')graph();else if(view==='timeline')timeline();else scenes();}
function graph(){const visible=targets.filter(t=>(t.name+' '+t.kind).toLowerCase().includes(filter.toLowerCase()));const points=new Map(visible.map((t,i)=>[t.id,{x:500+365*Math.cos(i*2*Math.PI/Math.max(visible.length,1)),y:300+235*Math.sin(i*2*Math.PI/Math.max(visible.length,1))}]));main.innerHTML=`<div class="page">${heading('TUDO ESTÁ CONECTADO','Conexões do mundo','Conecte personagens, documentos, criaturas, lugares e acontecimentos.',btn('＋ Nova conexão','newRelation'))}<input id="loreFilter" type="search" placeholder="Filtrar itens…" aria-label="Filtrar conexões" value="${e(filter)}"><div class="lore-graph"><svg viewBox="0 0 1000 600" role="group" aria-label="Grafo de conexões">${n.relations.filter(r=>points.has(r.from)&&points.has(r.to)).map(r=>{const a=points.get(r.from),b=points.get(r.to);return `<g><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-8}">${e(r.label)}</text></g>`;}).join('')}${visible.map(t=>{const p=points.get(t.id);return `<g class="lore-node" tabindex="0" role="button" aria-label="${e(t.name)}" data-target="${e(t.id)}"><circle cx="${p.x}" cy="${p.y}" r="20"/><text x="${p.x}" y="${p.y+40}">${e(t.name.slice(0,25))}</text></g>`;}).join('')}</svg>${!targets.length?'<p class="help">Suas fichas e páginas aparecerão aqui.</p>':''}</div><div class="lore-relations">${n.relations.map(r=>`<button class="lore-card" data-relation="${r.id}"><strong>${e(name(r.from))} → ${e(name(r.to))}</strong><span>${e(r.label)}</span><small>${e(r.description)}</small></button>`).join('')||'<p class="help">Adicione a primeira conexão para começar a desenhar sua rede.</p>'}</div><div id="lorePreview"></div></div>`;main.querySelector('[data-action="newRelation"]').onclick=()=>editRelation();main.querySelector('#loreFilter').onchange=ev=>{filter=ev.target.value;render();};main.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>editRelation(b.dataset.relation));main.querySelectorAll('[data-target]').forEach(b=>{b.onclick=()=>preview(b.dataset.target,main.querySelector('#lorePreview'));b.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();b.onclick();}};});}
function preview(id,container){const t=targets.find(x=>x.id===id);container.innerHTML=t?`<article class="lore-card"><small>${e(t.kind)}</small><h2>${e(t.name)}</h2><p>${e(t.description)}</p>${documentTargets(w).some(d=>d.id===id)?'<button class="button ghost" id="openLoreDoc">Abrir documento</button>':''}</article>`:'<p class="help">Esta referência foi removida.</p>';container.querySelector('#openLoreDoc')?.addEventListener('click',()=>openDocument(id));}
function timeline(){main.innerHTML=`<div class="page">${heading('O TEMPO DO SEU UNIVERSO','Linha do tempo','Uma cronologia própria para as histórias do seu mundo.',btn('＋ Novo evento','newLoreEvent'))}<div class="toolbar"><button class="button ghost" id="loreCalendar">⚙ Calendário fictício</button><span>${e(n.calendar.era)} · ${n.calendar.months.length} meses · ${n.calendar.weekdays.length} dias por semana</span></div><div class="lore-timeline">${[...n.events].sort((a,b)=>fictionalOrdinal(a,n.calendar)-fictionalOrdinal(b,n.calendar)).map(ev=>`<article class="lore-card"><small>${e(dateText(ev))} · ${e(n.calendar.weekdays[((fictionalOrdinal(ev,n.calendar)%n.calendar.weekdays.length)+n.calendar.weekdays.length)%n.calendar.weekdays.length])}</small><h2>${e(ev.title)}</h2><p>${e(ev.description)}</p>${ev.target?`<button class="text-link" data-target="${e(ev.target)}">↗ ${e(name(ev.target))}</button>`:''}<button class="button ghost" data-event="${ev.id}">Editar evento</button></article>`).join('')||'<div class="empty"><h2>Qual foi o primeiro acontecimento?</h2><p>Crie sua cronologia e conecte os eventos aos registros do mundo.</p></div>'}</div><div id="lorePreview"></div></div>`;main.querySelector('#loreCalendar').onclick=calendarSettings;main.querySelector('[data-action="newLoreEvent"]').onclick=()=>editEvent();main.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>editEvent(b.dataset.event));main.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>preview(b.dataset.target,main.querySelector('#lorePreview')));}
function scenes(){const scene=n.scenes.find(s=>s.id===selected)||n.scenes[0];selected=scene?.id||'';main.innerHTML=`<div class="page">${heading('ESCREVA COM SEU MUNDO POR PERTO','Cenas','Seu manuscrito, com as referências ao alcance dos olhos.',btn('＋ Nova cena','newScene'))}<div class="editor-layout scene-workspace"><nav class="note-list" aria-label="Cenas">${n.scenes.map(s=>`<button class="note-item ${s.id===selected?'active':''}" data-scene="${s.id}"><strong>${e(s.title)}</strong><small>${plain(s.body).split(/\s+/).filter(Boolean).length} palavras</small></button>`).join('')}</nav>${scene?`<section>${editorMarkup(scene).replace('<button class="text-link" data-action="deleteNote">Excluir documento</button>','')}<button class="text-link" id="deleteScene">Excluir cena</button></section><aside class="scene-references"><h2>Referências da cena</h2><label class="field"><span>Adicionar ficha ou documento</span><select id="sceneTarget">${options()}</select></label><div id="sceneRefs">${(scene.references||[]).map(id=>`<div class="scene-ref"><button class="text-link" data-preview="${e(id)}">${e(name(id))}</button><button class="icon-button" data-remove-ref="${e(id)}" aria-label="Remover referência">×</button></div>`).join('')}</div><label class="field"><span>Acontecimento na cronologia</span><select id="sceneEvent"><option value="">Sem evento</option>${n.events.map(ev=>`<option value="${ev.id}" ${scene.event===ev.id?'selected':''}>${e(ev.title)} · ${e(dateText(ev))}</option>`).join('')}</select></label><div id="scenePreview"><p class="help">Selecione uma referência para consultar seus detalhes enquanto escreve.</p></div></aside>`:'<div class="empty"><h2>Uma cena, muitas possibilidades.</h2><p>Crie a primeira cena para começar.</p></div>'}</div></div>`;main.querySelector('[data-action="newScene"]').onclick=()=>modal('Nova cena',field('Título','title','','text',true),fd=>{const s={id:uid(),title:fd.get('title'),body:'',references:[],updated:new Date().toISOString()};n.scenes.push(s);selected=s.id;save();render();});main.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{selected=b.dataset.scene;render();});if(!scene)return;dispose=mountEditor(scene,{onChange:save,onTitle:()=>{save();const b=main.querySelector('.note-item.active strong');if(b)b.textContent=scene.title;},notify,documents:documentTargets(w),openDocument});main.querySelector('#sceneTarget').onchange=ev=>{if(ev.target.value){scene.references=[...new Set([...(scene.references||[]),ev.target.value])];save();render();}};main.querySelector('#sceneEvent').onchange=ev=>{scene.event=ev.target.value;save();};main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.preview,main.querySelector('#scenePreview')));main.querySelectorAll('[data-remove-ref]').forEach(b=>b.onclick=()=>{scene.references=scene.references.filter(id=>id!==b.dataset.removeRef);save();render();});main.querySelector('#deleteScene').onclick=()=>confirmDelete('Excluir cena?','O texto desta cena será removido.',()=>n.scenes=n.scenes.filter(s=>s.id!==scene.id));}
render();return ()=>dispose();
}
